local CrustScorerMaker = {}
local PRODUCTS = {
    iron_crustscorer = { name = "Železni zarezovalec skorje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zarezovalec skorje za pekove." },
    bronze_crustscorer = { name = "Bronast zarezovalec skorje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zarezovalec skorje za pekove." },
    silver_crustscorer = { name = "Srebrn zarezovalec skorje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zarezovalec skorje za pekove." },
    gilded_crustscorer = { name = "Pozlačen zarezovalec skorje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zarezovalec skorje za pekove." },
    jewel_set_crustscorer = { name = "Draguljast zarezovalec skorje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zarezovalec skorje za pekove." },
    royal_sovereign_crustscorer = { name = "Kraljevski suveren zarezovalec skorje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zarezovalec skorje z biseri za krono." },
}
local BUILDINGS = {
    crustscorer_workshop = { name = "Crustscorer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    crustscorer_house = { name = "Crustscorer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_crustscorer_atelier = { name = "Mojstrski crustscorer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_crustscorer_palace = { name = "Suverena crustscorer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CrustScorerMaker.ironStock=16; CrustScorerMaker.bronzeStock=12; CrustScorerMaker.woodStock=12; CrustScorerMaker.leatherStock=8; CrustScorerMaker.silverStock=8; CrustScorerMaker.goldStock=6; CrustScorerMaker.jewelStock=4; CrustScorerMaker.pearlStock=4
CrustScorerMaker.productStock = {}; CrustScorerMaker.buildings = {}; CrustScorerMaker.maker = nil; CrustScorerMaker.activeMaking = {}; CrustScorerMaker.totalProducts = 0; CrustScorerMaker.dayTimer = 0
function CrustScorerMaker.init() CrustScorerMaker.ironStock=16; CrustScorerMaker.bronzeStock=12; CrustScorerMaker.woodStock=12; CrustScorerMaker.leatherStock=8; CrustScorerMaker.silverStock=8; CrustScorerMaker.goldStock=6; CrustScorerMaker.jewelStock=4; CrustScorerMaker.pearlStock=4; CrustScorerMaker.productStock={}; CrustScorerMaker.buildings={}; CrustScorerMaker.maker=nil; CrustScorerMaker.activeMaking={}; CrustScorerMaker.totalProducts=0; CrustScorerMaker.dayTimer=0; print("[CrustScorerMaker] Royal Crust Scorer Maker System initialized (6 products, 4 buildings)") end
function CrustScorerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrustScorerMaker.maker={name=n or ("Zarezovalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zarezovalec najet: %s (spretnost: %d)",CrustScorerMaker.maker.name,s),"success") end; return true end
function CrustScorerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrustScorerMaker.build(id) local ok,e=CrustScorerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrustScorerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrustScorerMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrustScorerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrustScorerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CrustScorerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CrustScorerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CrustScorerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CrustScorerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CrustScorerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrustScorerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrustScorerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrustScorerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrustScorerMaker.buildings==0 then return false,"Potrebna zarezna delavnica" end; if not CrustScorerMaker.maker then return false,"Potreben zarezovalec" end; return true end
function CrustScorerMaker.make(pt,qty) qty=qty or 1; local ok,e=CrustScorerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CrustScorerMaker.ironStock=CrustScorerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CrustScorerMaker.bronzeStock=CrustScorerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CrustScorerMaker.woodStock=CrustScorerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CrustScorerMaker.leatherStock=CrustScorerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CrustScorerMaker.silverStock=CrustScorerMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrustScorerMaker.goldStock=CrustScorerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrustScorerMaker.jewelStock=CrustScorerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrustScorerMaker.pearlStock=CrustScorerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrustScorerMaker.maker then t=math.max(1,t-math.floor(CrustScorerMaker.maker.skill/13)) end; table.insert(CrustScorerMaker.activeMaking,{id="crustscorer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrustScorerMaker.completeMaking(m) local q=1.0+(CrustScorerMaker.getQualityBonus()/100); if CrustScorerMaker.maker then q=q+(CrustScorerMaker.maker.skill/140) end; q=math.min(2.5,q); CrustScorerMaker.productStock[m.productType]=(CrustScorerMaker.productStock[m.productType] or 0)+m.quantity; CrustScorerMaker.totalProducts=CrustScorerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrustScorerMaker.maker then CrustScorerMaker.maker.itemsMade=CrustScorerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrustScorerMaker.maker.skill=math.min(100,CrustScorerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zarezovalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crustscorer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CrustScorerMaker.update(dt) if not _G.state then return end; CrustScorerMaker.dayTimer=CrustScorerMaker.dayTimer+dt; if CrustScorerMaker.dayTimer>=30 then CrustScorerMaker.dayTimer=0; for i=#CrustScorerMaker.activeMaking,1,-1 do local m=CrustScorerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrustScorerMaker.completeMaking(m); table.remove(CrustScorerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrustScorerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrustScorerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrustScorerMaker.getStats() return {ironStock=CrustScorerMaker.ironStock,bronzeStock=CrustScorerMaker.bronzeStock,woodStock=CrustScorerMaker.woodStock,leatherStock=CrustScorerMaker.leatherStock,silverStock=CrustScorerMaker.silverStock,goldStock=CrustScorerMaker.goldStock,jewelStock=CrustScorerMaker.jewelStock,pearlStock=CrustScorerMaker.pearlStock,productStock=CrustScorerMaker.productStock,numBuildings=#CrustScorerMaker.buildings,hasMaker=CrustScorerMaker.maker~=nil,makerName=CrustScorerMaker.maker and CrustScorerMaker.maker.name or "—",makerSkill=CrustScorerMaker.maker and CrustScorerMaker.maker.skill or 0,activeMaking=#CrustScorerMaker.activeMaking,totalProducts=CrustScorerMaker.totalProducts} end
return CrustScorerMaker
